import * as vscode from 'vscode';
import { AvatarManager } from './avatarManager';
import { BaseGitGraphView, createWebviewOptions } from './baseGitGraphView';
import { DataSource } from './dataSource';
import { ExtensionState } from './extensionState';
import { Logger } from './logger';
import { RepoManager } from './repoManager';
import { LoadGitGraphViewTo } from './types';
import { toDisposable } from './utils/disposable';

/**
 * The commands that reveal the Webview View of the panel, in the order they are tried. The first is generated by Visual
 * Studio Code for the view, the second opens the view container (for when the view itself can't be focused).
 */
const REVEAL_PANEL_COMMANDS = ['easy-graph.panel.focus', 'workbench.view.extension.easy-graph-panel'];

/**
 * Manages the Git Graph View in the panel. A single instance exists for the lifetime of the extension, and is registered as
 * the provider of the `easy-graph.panel` Webview View. Visual Studio Code resolves the Webview View when it's first shown,
 * and again whenever it was disposed in the meantime (e.g. after the view was closed or moved to another container), each
 * time with a new webview that is attached to this instance.
 */
export class GitGraphPanelView extends BaseGitGraphView implements vscode.WebviewViewProvider {
	public static readonly viewType = 'easy-graph.panel';
	private static instance: GitGraphPanelView | null = null;

	private webviewView: vscode.WebviewView | null = null;
	private webviewViewSubscriptions: vscode.Disposable[] = [];

	/**
	 * Get the Git Graph View in the panel, creating it on first use.
	 * @param extensionPath The absolute file path of the directory containing the extension.
	 * @param dataSource The Git Graph DataSource instance.
	 * @param extensionState The Git Graph ExtensionState instance.
	 * @param avatarManger The Git Graph AvatarManager instance.
	 * @param repoManager The Git Graph RepoManager instance.
	 * @param logger The Git Graph Logger instance.
	 * @returns The Git Graph View in the panel.
	 */
	public static getInstance(extensionPath: string, dataSource: DataSource, extensionState: ExtensionState, avatarManager: AvatarManager, repoManager: RepoManager, logger: Logger): GitGraphPanelView {
		if (GitGraphPanelView.instance === null) {
			GitGraphPanelView.instance = new GitGraphPanelView(extensionPath, dataSource, extensionState, avatarManager, repoManager, logger);
		}
		return GitGraphPanelView.instance;
	}

	/**
	 * Creates the Git Graph View in the panel. Nothing is rendered until Visual Studio Code resolves the Webview View.
	 */
	private constructor(extensionPath: string, dataSource: DataSource, extensionState: ExtensionState, avatarManager: AvatarManager, repoManager: RepoManager, logger: Logger) {
		super(extensionPath, dataSource, extensionState, avatarManager, repoManager, logger, null);
		this.registerDisposables(
			toDisposable(() => {
				this.releaseWebviewView();
				if (GitGraphPanelView.instance === this) GitGraphPanelView.instance = null;
			})
		);
	}

	/**
	 * Render the view in a (new) Webview View resolved by Visual Studio Code.
	 * @param webviewView The Webview View.
	 */
	public resolveWebviewView(webviewView: vscode.WebviewView) {
		this.releaseWebviewView();
		this.webviewView = webviewView;
		webviewView.webview.options = createWebviewOptions(this.extensionPath);
		this.webviewViewSubscriptions = [
			webviewView.onDidChangeVisibility(() => this.onDidChangeVisibility(webviewView.visible)),
			webviewView.onDidDispose(() => {
				if (this.webviewView === webviewView) this.releaseWebviewView();
			})
		];
		// The front-end restores its own view state (scroll position, expanded commit, ...) with `getState`, the extension
		// only needs to render the view again
		this.attachWebview(webviewView.webview, webviewView.visible);
	}

	/**
	 * Show the view in the panel, and load it to the requested target.
	 * @param loadViewTo What to load the view to.
	 */
	public async show(loadViewTo: LoadGitGraphViewTo) {
		const webviewView = this.webviewView;
		if (webviewView !== null) {
			webviewView.show(true);
			this.updateWithRepos(this.repoManager.getRepos(), loadViewTo);
			return;
		}

		// The Webview View hasn't been resolved yet (or was disposed). Revealing it makes Visual Studio Code resolve it,
		// which renders the view with the pending target. If it doesn't, the target is used once it's resolved.
		this.loadViewTo = loadViewTo;
		for (const command of REVEAL_PANEL_COMMANDS) {
			try {
				await vscode.commands.executeCommand(command);
				return;
			} catch {
				// Try the next command
			}
		}
		this.logger.logError('Failed to reveal the Easy Graph panel');
	}

	/**
	 * Is the Webview View currently visible.
	 */
	protected isHostVisible() {
		return this.webviewView !== null && this.webviewView.visible;
	}

	/**
	 * Stop using the current Webview View (if any), e.g. because it was disposed.
	 */
	private releaseWebviewView() {
		this.webviewViewSubscriptions.forEach((disposable) => disposable.dispose());
		this.webviewViewSubscriptions = [];
		this.webviewView = null;
		this.detachWebview();
	}
}
